00051 std::string GetBlockStatisticName(BlockStatistic statistic)
00052 {
00053   auto statisticIterator = blockstatistic2description.find(statistic);
00054   // enforces that all delcared statistic enum items are also part of the map
00055   assert(statisticIterator != blockstatistic2description.end() && "A block statistics declared in the enum is missing in the map for statistic description.");
00056 
00057   return std::get<0>(statisticIterator->second);
00058 }
00059 
00060 std::string GetBlockStatisticTypeString(BlockStatistic statistic)
00061 {
00062   auto statisticIterator = blockstatistic2description.find(statistic);
00063   // enforces that all delcared statistic enum items are also part of the map
00064   assert(statisticIterator != blockstatistic2description.end() && "A block statistics declared in the enum is missing in the map for statistic description.");
00065 
00066   BlockStatisticType statisticType = std::get<1>(statisticIterator->second);
00067   switch (statisticType) {
00068   case BlockStatisticType::Flag:
00069     return std::string("Flag");
00070     break;
00071   case BlockStatisticType::Vector:
00072     return std::string("Vector");
00073     break;
00074   case BlockStatisticType::Integer:
00075     return std::string("Integer");
00076     break;
00077   case BlockStatisticType::AffineTFVectors:
00078     return std::string("AffineTFVectors");
00079     break;
00080   case BlockStatisticType::Line:
00081     return std::string("Line");
00082     break;
00083   case BlockStatisticType::FlagPolygon:
00084     return std::string("FlagPolygon");
00085     break;
00086   case BlockStatisticType::VectorPolygon:
00087     return std::string("VectorPolygon");
00088     break;
00089   case BlockStatisticType::IntegerPolygon:
00090     return std::string("IntegerPolygon");
00091     break;
00092   default:
00093     assert(0);
00094     break;
00095   }
00096   return std::string();
00097 }
