00256 void CDTrace::dtrace_polygon_scalar(int k, int poc, const std::vector<Position> &polygon, std::string stat_type, signed value)
00257 {
00258   assert(polygon.size() >= BLOCK_STATS_POLYGON_MIN_POINTS && "Not enough points to from polygon!");
00259   assert(polygon.size() <= BLOCK_STATS_POLYGON_MAX_POINTS && "Too many points. Unsupported polygon!");
00260   std::string polygonDescription;
00261 #if BLOCK_STATS_AS_CSV
00262   for (auto position : polygon)
00263   {
00264     polygonDescription += std::to_string(position.x) + ";" + std::to_string(position.y) + ";";
00265   }
00266 
00267   dtrace<false>( k, "BlockStat;%d;%s%s;%d\n",poc, polygonDescription.c_str(), stat_type.c_str(), value);
00268 #else
00269   for (auto position : polygon)
00270   {
00271     polygonDescription += "(" + std::to_string(position.x) + ", " + std::to_string(position.y) + ")--";
00272   }
00273 
00274   dtrace<false>(k, "BlockStat: POC %d @[%s] %s=%d\n", poc, polygonDescription.c_str(), stat_type.c_str(), value);
00275 #endif
00276 }
00277 
