00300 void retrieveGeoPolygons(const CodingUnit& cu, std::vector<Position> (&geoPartitions)[2], Position (&linePositions)[2])
00301 {
00302   // adapted code from interpolation filter to find geo partition polygons like this:
00303   // use SAD mask, which should clearly partition the two polygons.
00304   // loop over boundary pixels and find positions where there is a change, these should be the polygon corners
00305   static bool isInitialized = false;
00306   static std::vector<Position> allGeoPartitionings[GEO_NUM_CU_SIZE][GEO_NUM_CU_SIZE][GEO_NUM_PARTITION_MODE][2];
00307   static Position allGeoPartitioningLines[GEO_NUM_CU_SIZE][GEO_NUM_CU_SIZE][GEO_NUM_PARTITION_MODE][2];
00308 
00309   if(!isInitialized)
00310   {
00311     for( int hIdx = 0; hIdx < GEO_NUM_CU_SIZE; hIdx++ )
00312     {
00313       int16_t height = 1 << ( hIdx + GEO_MIN_CU_LOG2);
00314       for( int wIdx = 0; wIdx < GEO_NUM_CU_SIZE; wIdx++ )
00315       {
00316         int16_t width = 1 << (wIdx + GEO_MIN_CU_LOG2);
00317         for( int splitDir = 0; splitDir < GEO_NUM_PARTITION_MODE; splitDir++ )
00318         {
00319           int16_t angle         = g_GeoParams[splitDir][0];
00320 
00321           int maskStride = 0;
00322           int stepX = 1;
00323           Pel* SADmask;
00324           if (g_angle2mirror[angle] == 2)
00325           {
00326             maskStride = -GEO_WEIGHT_MASK_SIZE;
00327             SADmask = &g_globalGeoEncSADmask[g_angle2mask[g_GeoParams[splitDir][0]]][(GEO_WEIGHT_MASK_SIZE - 1 - g_weightOffset[splitDir][hIdx][wIdx][1]) * GEO_WEIGHT_MASK_SIZE + g_weightOffset[splitDir][hIdx][wIdx][0]];
00328           }
00329           else if (g_angle2mirror[angle] == 1)
00330           {
00331             stepX = -1;
00332             maskStride = GEO_WEIGHT_MASK_SIZE;
00333             SADmask = &g_globalGeoEncSADmask[g_angle2mask[g_GeoParams[splitDir][0]]][g_weightOffset[splitDir][hIdx][wIdx][1] * GEO_WEIGHT_MASK_SIZE + (GEO_WEIGHT_MASK_SIZE - 1 - g_weightOffset[splitDir][hIdx][wIdx][0])];
00334           }
00335           else
00336           {
00337             maskStride = GEO_WEIGHT_MASK_SIZE;
00338             SADmask = &g_globalGeoEncSADmask[g_angle2mask[g_GeoParams[splitDir][0]]][g_weightOffset[splitDir][hIdx][wIdx][1] * GEO_WEIGHT_MASK_SIZE + g_weightOffset[splitDir][hIdx][wIdx][0]];
00339           }
00340 
00341           int currentPartition = 0;
00342           std::vector<Pel> boundaryOfMask; // for debugging
00343 
00344           Area partitionArea = Area(0, 0, width, height);
00345           Position TL = partitionArea.topLeft();
00346           Position TR = partitionArea.topRight();    TR = TR.offset(1, 0);
00347           Position BL = partitionArea.bottomLeft();  BL = BL.offset(0, 1);
00348           Position BR = partitionArea.bottomRight(); BR = BR.offset(1, 1);
00349 
00350           std::vector<Position> oneGeoPartitioning[2];
00351           Position oneGeoPartitioningLine[2];
00352           // corner of block is a corner of the first partition
00353           oneGeoPartitioning[currentPartition].push_back(TL);
00354 
00355           // process top boundary
00356           for( int x = 0; x < width-1; x++ )
00357           {
00358             boundaryOfMask.push_back(*SADmask);
00359             if(*SADmask != *(SADmask+stepX))
00360             {
00361               // found a change of partitions, it is a corner of both partition polygons
00362               oneGeoPartitioning[currentPartition].push_back(Position(TL.x + x, TL.y));
00363               oneGeoPartitioningLine[currentPartition] = Position(TL.x + x, TL.y);
00364               currentPartition ^= 0x01;
00365               oneGeoPartitioning[currentPartition].push_back(Position(TL.x + x, TL.y));
00366             }
00367             SADmask += stepX;
00368           }
00369 
00370           // corner of block is a corner of the current partition
00371           oneGeoPartitioning[currentPartition].push_back(TR);
00372 
00373           // process right boundary
00374           for( int y = 0; y < height-1; y++ )
00375           {
00376             boundaryOfMask.push_back(*SADmask);
00377             if(*SADmask != *(SADmask+maskStride))
00378             {
00379               // found a change of partitions, it is a corner of both partition polygons
00380               oneGeoPartitioning[currentPartition].push_back(Position(TR.x, TR.y + y));
00381               oneGeoPartitioningLine[currentPartition] = Position(TR.x, TR.y + y);
00382               currentPartition ^= 0x01;
00383               oneGeoPartitioning[currentPartition].push_back(Position(TR.x, TR.y + y));
00384             }
00385             SADmask += maskStride;
00386           }
00387 
00388           // corner of block is a corner of the current partition
00389           oneGeoPartitioning[currentPartition].push_back(BR);
00390 
00391           // process bottom boundary
00392           for( int x = width-1; x > 0; x-- )
00393           {
00394             boundaryOfMask.push_back(*SADmask);
00395             if(*SADmask != *(SADmask-stepX))
00396             {
00397               // found a change of partitions, it is a corner of both partition polygons
00398               oneGeoPartitioning[currentPartition].push_back(Position(BL.x + x, BL.y));
00399               oneGeoPartitioningLine[currentPartition] = Position(BL.x + x, BL.y);
00400               currentPartition ^= 0x01;
00401               oneGeoPartitioning[currentPartition].push_back(Position(BL.x + x, BL.y));
00402             }
00403             SADmask -= stepX;
00404           }
00405 
00406           // corner of block is a corner of the current partition
00407           oneGeoPartitioning[currentPartition].push_back(BL);
00408 
00409           // process left boundary
00410           for( int y = height-1; y > 0; y-- )
00411           {
00412             boundaryOfMask.push_back(*SADmask);
00413             if(*SADmask != *(SADmask-maskStride))
00414             {
00415               // found a change of partitions, it is a corner of both partition polygons
00416               oneGeoPartitioning[currentPartition].push_back(Position(TL.x, TL.y + y));
00417               oneGeoPartitioningLine[currentPartition] = Position(TL.x, TL.y + y);
00418               currentPartition ^= 0x01;
00419               oneGeoPartitioning[currentPartition].push_back(Position(TL.x, TL.y + y));
00420             }
00421             SADmask -= maskStride;
00422           }
00423 
00424           // corner of block is a corner of the current partition
00425           oneGeoPartitioning[currentPartition].push_back(TL);
00426 
00427           // remove duplicate points
00428           for( auto geoPartIdx = 0; geoPartIdx < 2; geoPartIdx++)
00429           {
00430             // this will only remove consecutive duplicates
00431             auto last = std::unique(oneGeoPartitioning[geoPartIdx].begin(), oneGeoPartitioning[geoPartIdx].end());
00432             oneGeoPartitioning[geoPartIdx].erase(last, oneGeoPartitioning[geoPartIdx].end());
00433             // also check if first and last are the same
00434             if(oneGeoPartitioning[geoPartIdx].front() == oneGeoPartitioning[geoPartIdx].back())
00435             {
00436               oneGeoPartitioning[geoPartIdx].pop_back();
00437             }
00438 
00439             CHECK(!(oneGeoPartitioning[geoPartIdx].size() > 2 && oneGeoPartitioning[geoPartIdx].size() < 6), "Invalid geo partition shape. Polygon should have between 3 and 5 corners.");
00440           }
00441 
00442           allGeoPartitionings[hIdx][wIdx][splitDir][0] = oneGeoPartitioning[0];
00443           allGeoPartitionings[hIdx][wIdx][splitDir][1] = oneGeoPartitioning[1];
00444           allGeoPartitioningLines[hIdx][wIdx][splitDir][0] = oneGeoPartitioningLine[0];
00445           allGeoPartitioningLines[hIdx][wIdx][splitDir][1] = oneGeoPartitioningLine[1];
00446         }
00447       }
00448     }
00449     isInitialized = true;
00450   }
00451 
00452   const uint8_t splitDir = cu.firstPU->geoSplitDir;
00453   int16_t wIdx = floorLog2(cu.lwidth()) - GEO_MIN_CU_LOG2;
00454   int16_t hIdx = floorLog2(cu.lheight()) - GEO_MIN_CU_LOG2;
00455 
00456   Position TL = cu.Y().topLeft();
00457 
00458   geoPartitions[0] = allGeoPartitionings[hIdx][wIdx][splitDir][0];
00459   geoPartitions[1] = allGeoPartitionings[hIdx][wIdx][splitDir][1];
00460   linePositions[0] = allGeoPartitioningLines[hIdx][wIdx][splitDir][0];
00461   linePositions[1] = allGeoPartitioningLines[hIdx][wIdx][splitDir][1];
00462 
00463   // offset the partitioning to the current cu
00464   for( auto geoPartIdx = 0; geoPartIdx < 2; geoPartIdx++)
00465   {
00466     for( Position &polygonCorner : geoPartitions[geoPartIdx])
00467     {
00468       polygonCorner.repositionTo(polygonCorner.offset(TL));
00469     }
00470   }
00471 }
